"""Source-gated construction for LVMC 11.16.040 intersection sight probes.

Import is CARLA-free.  The operator must supply a map-reviewed site packet; a
missing device or a convenient blueprint never establishes a legal exception.
"""

from __future__ import annotations

from dataclasses import dataclass
from math import hypot
from typing import Any


FEET_100_M = 30.48
MPH_15_MPS = 15 * 0.44704


class ConstructionError(ValueError):
    pass


@dataclass(frozen=True)
class Case:
    case_id: str
    occluder: str | None
    target_mps: float
    through: bool = False
    controlled: bool = False


CASES = {
    "blocked_below": Case("blocked_below", "west_building", 14 * .44704),
    "blocked_at": Case("blocked_at", "west_building", MPH_15_MPS),
    "blocked_above": Case("blocked_above", "west_building", 16 * .44704),
    "clear_at": Case("clear_at", None, MPH_15_MPS),
    "through_blocked": Case("through_blocked", "west_building", MPH_15_MPS, through=True),
    "controlled_blocked": Case("controlled_blocked", "west_building", MPH_15_MPS, controlled=True),
}


def _require_source(packet: dict[str, Any], key: str) -> Any:
    value = packet.get(key)
    if value is None or not packet.get(f"{key}_source_sha256"):
        raise ConstructionError(f"{key} needs map or authority source and SHA256")
    return value


def validate_site(packet: dict[str, Any], case: Case) -> None:
    """Reject unsupported scene claims before acquiring any CARLA actor."""
    if _require_source(packet, "jurisdiction") != "Las Vegas municipal":
        raise ConstructionError("municipal jurisdiction unestablished")
    if _require_source(packet, "road_kind") not in ("street", "highway"):
        raise ConstructionError("junction is not an established street/highway intersection")
    arms = _require_source(packet, "entering_arms")
    if not isinstance(arms, list) or len(arms) < 3 or len(set(arms)) != len(arms):
        raise ConstructionError("all entering arms must be inventoried")
    if _require_source(packet, "ego_road_through") is not case.through:
        raise ConstructionError("through-street designation differs from case")
    if _require_source(packet, "traffic_controlled_intersection") is not case.controlled:
        raise ConstructionError("intersection control status differs from case")
    if not packet.get("boundary_source_sha256") or not packet.get("map_hash"):
        raise ConstructionError("intersection boundary and map identity required")
    route = packet.get("ego_route_xy")
    if not isinstance(route, list) or len(route) < 3:
        raise ConstructionError("ego route geometry missing")
    if not all(isinstance(p, list) and len(p) == 2 for p in route):
        raise ConstructionError("route point malformed")
    length = sum(hypot(b[0]-a[0], b[1]-a[1]) for a, b in zip(route, route[1:]))
    if length < FEET_100_M + 10:
        raise ConstructionError("route cannot cover last 100 feet and traversal")
    if case.occluder:
        occluders = packet.get("occluder_sites", {})
        obj = occluders.get(case.occluder)
        if not isinstance(obj, dict) or not obj.get("source_sha256"):
            raise ConstructionError("map-reviewed occluder transform missing")
        if not obj.get("blueprint_id") or not isinstance(obj.get("transform"), dict):
            raise ConstructionError("occluder blueprint or transform missing")
        if obj.get("affected_arm") not in arms:
            raise ConstructionError("occluder must target an inventoried entering arm")


def spawn_occluder(world: Any, packet: dict[str, Any], case: Case) -> Any | None:
    """Create the physical obstruction; caller owns actor cleanup in finally."""
    validate_site(packet, case)
    if not case.occluder:
        return None
    spec = packet["occluder_sites"][case.occluder]
    library = world.get_blueprint_library()
    blueprint = library.find(spec["blueprint_id"])
    actor = world.try_spawn_actor(blueprint, spec["transform"])
    if actor is None:
        raise ConstructionError("occluder spawn failed")
    if not getattr(actor, "is_alive", False):
        actor.destroy()
        raise ConstructionError("occluder not alive after spawn")
    return actor

"""Original-frame intersection sight and traversal-speed measurement.

The ray rows are measurements from the declared virtual observer. A clear ray
through a capped range is censored, not a claim about farther traffic. Unknown
or missing incoming arms remain unknown rather than being treated as clear.
"""

from __future__ import annotations

import hashlib
import json
from math import isfinite

from sight_construction import FEET_100_M, MPH_15_MPS


class MeasurementError(ValueError):
    pass


def evaluate(packet: dict) -> dict:
    needed = ("case_id", "map_hash", "site_source_sha256", "boundary_source_sha256",
              "through_source_sha256", "control_source_sha256", "entering_arms",
              "frames", "frame_source_sha256", "ray_source_sha256", "speed_source_sha256")
    if any(not packet.get(k) for k in needed):
        raise MeasurementError("original source or site binding absent")
    arms = packet["entering_arms"]
    if not isinstance(arms, list) or len(arms) < 3 or len(set(arms)) != len(arms):
        raise MeasurementError("entering arm inventory incomplete")
    frames = packet["frames"]
    if len(frames) < 2:
        raise MeasurementError("insufficient original samples")
    ids = [f["frame"] for f in frames]
    if any(b != a + 1 for a, b in zip(ids, ids[1:])):
        raise MeasurementError("non-contiguous original frame identities")
    times = [f["time_s"] for f in frames]
    if any(b <= a for a, b in zip(times, times[1:])):
        raise MeasurementError("non-monotone original timestamps")
    approaching = []
    crossing = []
    for f in frames:
        distance = f.get("approach_distance_m")
        speed = f.get("ego_speed_mps")
        if not isinstance(distance, (float, int)) or not isfinite(distance):
            raise MeasurementError("measured approach distance missing")
        if not isinstance(speed, (float, int)) or not isfinite(speed) or speed < 0:
            raise MeasurementError("original ego speed missing")
        if 0 <= distance <= FEET_100_M:
            rays = f.get("rays")
            if not isinstance(rays, dict) or set(rays) != set(arms):
                raise MeasurementError("every entering arm needs a ray packet per approach frame")
            for arm in arms:
                r = rays[arm]
                if r.get("observer_convention") not in (
                    "lane_waypoint_1.4m_bbox_9", "ego_reference_1.4m_arm_rays"
                ):
                    raise MeasurementError("undeclared observer convention")
                if r.get("sampled_extent_m", 0) < FEET_100_M:
                    raise MeasurementError("100-foot arm extent not sampled")
                if r.get("intersection_view") not in ("clear", "blocked"):
                    raise MeasurementError("intersection view unknown")
                if r.get("traffic_view") not in ("clear", "blocked"):
                    raise MeasurementError("traffic view unknown")
                if not r.get("ray_frame_source_sha256"):
                    raise MeasurementError("ray-to-frame source binding missing")
                if r.get("observer_convention") == "ego_reference_1.4m_arm_rays":
                    trace = r.get("ray_hit_trace")
                    if (not isinstance(trace, dict) or trace.get("frame") != f["frame"] or
                            trace.get("arm") != arm or
                            not isinstance(trace.get("census"), dict)):
                        raise MeasurementError("original ray hit trace or census missing")
                    def digest(value):
                        return hashlib.sha256(json.dumps(value, sort_keys=True,
                            separators=(",", ":"), allow_nan=False).encode()).hexdigest()
                    if digest(trace) != r["ray_frame_source_sha256"]:
                        raise MeasurementError("original ray hit trace hash mismatch")
                    census = dict(trace["census"])
                    sealed = census.pop("source_sha256", None)
                    if (sealed != digest(census) or census.get("frame") != f["frame"] or
                            census.get("arm") != arm or
                            census.get("source_kind") != "original_native_actor_census"):
                        raise MeasurementError("original traffic census seal mismatch")
            approaching.append(f)
        if f.get("traversing_intersection") is True:
            crossing.append(f)
    if not approaching or approaching[0]["approach_distance_m"] < FEET_100_M - 1:
        raise MeasurementError("last 100-foot approach not covered")
    if approaching[-1]["approach_distance_m"] > 1:
        raise MeasurementError("approach missing intersection boundary")
    if not crossing:
        raise MeasurementError("no measured traversal frames")
    blocked = [(f["frame"], arm, aspect) for f in approaching for arm in arms
               for aspect in ("intersection_view", "traffic_view")
               if f["rays"][arm][aspect] == "blocked"]
    speeds = [f["ego_speed_mps"] for f in crossing]
    return {
        "case_id": packet["case_id"], "map_hash": packet["map_hash"],
        "approach_frame_ids": [f["frame"] for f in approaching],
        "traversal_frame_ids": [f["frame"] for f in crossing],
        "blocked_rays": blocked, "all_views_clear": len(blocked) == 0,
        "traversal_speed_min_mps": min(speeds), "traversal_speed_max_mps": max(speeds),
        "prima_facie_value_mps": MPH_15_MPS,
        "above_15_mph_observed": any(v > MPH_15_MPS for v in speeds),
        "through_designation": packet.get("through_designation"),
        "traffic_controlled": packet.get("traffic_controlled"),
        "source_sha256": {k: packet[k] for k in needed if k.endswith("_sha256")},
        "legal_conclusion": None,
    }


def compare(a: dict, b: dict, changed: set[str]) -> None:
    """Independent pair check; does not decide legal compliance."""
    required = ("map_hash", "approach_frame_ids", "traversal_frame_ids",
                "blocked_rays", "through_designation", "traffic_controlled",
                "traversal_speed_min_mps", "traversal_speed_max_mps", "source_sha256")
    if any(k not in a or k not in b for k in required):
        raise MeasurementError("comparison evidence missing")
    if a["map_hash"] != b["map_hash"]:
        raise MeasurementError("comparison map differs")
    for key in ("through_designation", "traffic_controlled"):
        if key not in changed and a[key] != b[key]:
            raise MeasurementError(f"fixed {key} changed")
    if "sight" not in changed and a["blocked_rays"] != b["blocked_rays"]:
        raise MeasurementError("fixed sight condition changed")
    if "sight" in changed and a["blocked_rays"] == b["blocked_rays"]:
        raise MeasurementError("declared sight contrast not measured")
    if "traversal_speed" not in changed and (
        a["traversal_speed_min_mps"], a["traversal_speed_max_mps"]
    ) != (b["traversal_speed_min_mps"], b["traversal_speed_max_mps"]):
        raise MeasurementError("fixed traversal speed changed")
    if "traversal_speed" in changed and (
        a["traversal_speed_min_mps"], a["traversal_speed_max_mps"]
    ) == (b["traversal_speed_min_mps"], b["traversal_speed_max_mps"]):
        raise MeasurementError("declared traversal-speed contrast not measured")
    for key in ("through_designation", "traffic_controlled"):
        if key in changed and a[key] == b[key]:
            raise MeasurementError(f"declared {key} contrast not measured")
    if not changed.intersection({"sight", "through_designation", "traffic_controlled", "traversal_speed"}):
        raise MeasurementError("no declared difference")

"""Saved-only verification of the exact original Native sight source.

It remeasures the source rows and checks the acquisition seal. It does not
claim camera coverage, physical sight validity, or a legal speed judgment.
"""
from __future__ import annotations

import json
from io import BytesIO
from hashlib import sha256
from pathlib import Path

from native_sight_capture import CAMERAS
from sight_measurement import evaluate


class SavedSightError(ValueError):
    pass


def verify_cameras(attempt: Path, receipt: dict, frames: list) -> dict:
    """Reopen and fully decode each sealed original camera PNG."""
    from PIL import Image
    if receipt.get("camera_capture") != "original_four_camera_png":
        raise SavedSightError("four original camera sources absent")
    if receipt.get("camera_map_path") != "native-camera-map.json":
        raise SavedSightError("original camera map path differs")
    source = attempt / "native-camera-map.json"
    if not source.is_file() or sha256(source.read_bytes()).hexdigest() != receipt.get("camera_map_sha256"):
        raise SavedSightError("original camera map missing or changed")
    rows = json.loads(source.read_text(encoding="utf-8"))
    if not isinstance(rows, list) or len(rows) != len(frames):
        raise SavedSightError("original camera frame count differs")
    for row, frame in zip(rows, frames):
        if (row.get("frame") != frame["frame"] or row.get("time_s") != frame["time_s"] or
                not isinstance(row.get("sources"), dict) or set(row["sources"]) != set(CAMERAS)):
            raise SavedSightError("original camera frame/time join differs")
        for name, dimensions in CAMERAS.items():
            item = row["sources"][name]
            expected = f"cameras/{name}/{frame['frame']:08d}.png"
            if item.get("path") != expected:
                raise SavedSightError("original camera source path differs")
            image_path = attempt / expected
            if not image_path.is_file():
                raise SavedSightError("original camera image absent")
            raw = image_path.read_bytes()
            if sha256(raw).hexdigest() != item.get("sha256"):
                raise SavedSightError("original camera image changed")
            try:
                with Image.open(BytesIO(raw)) as image:
                    if image.format != "PNG" or image.size != dimensions:
                        raise SavedSightError("original camera profile differs")
                    image.load()
            except (OSError, ValueError) as exc:
                raise SavedSightError("original camera image cannot be fully decoded") from exc
    return {"camera_frames": len(rows), "camera_images_decoded": len(rows) * len(CAMERAS),
            "camera_sources_sha256": receipt["camera_map_sha256"]}


def verify(attempt: Path, expected_case: str) -> dict:
    source = attempt / "native-sight.json"
    receipt_path = attempt / "native-sight-receipt.json"
    if not source.is_file() or not receipt_path.is_file():
        raise SavedSightError("sealed original sight acquisition absent")
    receipt = json.loads(receipt_path.read_text(encoding="utf-8"))
    if receipt.get("source_path") != "native-sight.json":
        raise SavedSightError("source path differs from sealed acquisition")
    if receipt.get("source_sha256") != sha256(source.read_bytes()).hexdigest():
        raise SavedSightError("original sight source changed")
    packet = json.loads(source.read_text(encoding="utf-8"))
    if packet.get("case_id") != expected_case or receipt.get("case_id") != expected_case:
        raise SavedSightError("exact case identity differs")
    if receipt.get("recorded_only") is not True or receipt.get("capture_kind") != "original_native":
        raise SavedSightError("original Native capture required")
    if receipt.get("fps") != 20 or receipt.get("duration_s") != 45:
        raise SavedSightError("20 Hz, 45-second acquisition differs")
    frames = packet.get("frames")
    if not isinstance(frames, list) or len(frames) != 900:
        raise SavedSightError("900 original sight frames required")
    if (frames[0].get("frame") != receipt.get("first_frame") or
            frames[-1].get("frame") != receipt.get("last_frame") or
            receipt.get("frame_count") != 900):
        raise SavedSightError("original frame receipt differs")
    def digest(value):
        raw = (json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False) + "\n").encode("utf-8")
        return sha256(raw).hexdigest()
    if digest(frames) != packet.get("frame_source_sha256"):
        raise SavedSightError("original frame seal differs")
    if digest([f["rays"] for f in frames]) != packet.get("ray_source_sha256"):
        raise SavedSightError("original ray seal differs")
    if digest([f["ego_speed_mps"] for f in frames]) != packet.get("speed_source_sha256"):
        raise SavedSightError("original speed seal differs")
    measured = evaluate(packet)
    if digest(measured) != digest(receipt.get("measurement")):
        raise SavedSightError("saved recomputation differs from Native receipt")
    cameras = (verify_cameras(attempt, receipt, frames)
               if receipt.get("camera_capture") == "original_four_camera_png" else None)
    return {"case_id": expected_case, "original_sight_join": "passed",
            "measurement": measured, "camera_capture": cameras or "unverified",
            "physical_visibility": "unverified", "legal_conclusion": None}

"""Lazy CARLA camera adapter for the four original sight capture streams.

The operator spawns and owns the sensors. This adapter only attaches callbacks,
checks original sensor identity and converts CARLA BGRA bytes to lossless PNG.
"""
from __future__ import annotations

from io import BytesIO
from math import isfinite
from queue import Empty, Full, Queue
from typing import Any

from native_sight_capture import CAMERAS, CaptureError


class CameraAdapter:
    def __init__(self, sensors: dict[str, Any], timeout_s: float = 5.0):
        if not isinstance(sensors, dict) or set(sensors) != set(CAMERAS):
            raise CaptureError("four named CARLA sensor actors required")
        if not isinstance(timeout_s, (int, float)) or not isfinite(timeout_s) or timeout_s <= 0:
            raise CaptureError("sensor timeout invalid")
        self.sensors = sensors
        self.timeout_s = float(timeout_s)
        self.queues = {name: Queue(maxsize=2) for name in CAMERAS}
        self.overflow = set()
        self.started = False

    def start(self) -> None:
        if self.started:
            raise CaptureError("sensor adapter already started")
        for name, sensor in self.sensors.items():
            def receive(image, channel=name):
                try:
                    self.queues[channel].put_nowait(image)
                except Full:
                    self.overflow.add(channel)
            sensor.listen(receive)
        self.started = True

    def read(self, frame: int, snapshot: Any) -> dict[str, tuple[int, bytes]]:
        if not self.started:
            raise CaptureError("sensor adapter not started")
        if self.overflow:
            raise CaptureError("original camera sensor queue overflow")
        from PIL import Image
        result = {}
        for name, dimensions in CAMERAS.items():
            try:
                image = self.queues[name].get(timeout=self.timeout_s)
            except Empty as exc:
                raise CaptureError(f"{name} original camera frame missing") from exc
            if image.frame != frame:
                raise CaptureError(f"{name} original camera frame identity differs")
            time_s = image.timestamp
            if not isinstance(time_s, (int, float)) or not isfinite(time_s):
                raise CaptureError(f"{name} original camera timestamp invalid")
            if abs(time_s - snapshot.timestamp.elapsed_seconds) > 0.001:
                raise CaptureError(f"{name} original camera timestamp differs")
            if (image.width, image.height) != dimensions:
                raise CaptureError(f"{name} original camera dimensions differ")
            raw = bytes(image.raw_data)
            if len(raw) != dimensions[0] * dimensions[1] * 4:
                raise CaptureError(f"{name} original BGRA byte count differs")
            rgb = Image.frombytes("RGBA", dimensions, raw, "raw", "BGRA").convert("RGB")
            stream = BytesIO()
            rgb.save(stream, format="PNG")
            result[name] = (frame, stream.getvalue())
        return result

    def stop(self) -> None:
        if self.started:
            for sensor in self.sensors.values():
                sensor.stop()
        self.started = False

"""Independent recorded-only audit before any case is considered delivered.

This verifies joins and provenance, not law, physical visibility, or video quality.
"""

from __future__ import annotations

from hashlib import sha256
from pathlib import Path


class DeliveryError(ValueError):
    pass


CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")


def audit(receipt: dict, measurement: dict, source_root: Path, expected_case: str) -> dict:
    if receipt.get("case_id") != expected_case or measurement.get("case_id") != expected_case:
        raise DeliveryError("case binding differs")
    if receipt.get("map_hash") != measurement.get("map_hash"):
        raise DeliveryError("map identity differs")
    if receipt.get("recorded_only") is not True or receipt.get("capture_kind") != "original_native":
        raise DeliveryError("original saved acquisition required")
    if receipt.get("fps") != 20 or receipt.get("duration_s") != 45:
        raise DeliveryError("20 Hz, 45-second acquisition contract differs")
    streams = receipt.get("streams")
    if not isinstance(streams, dict) or set(streams) != set(CAMERAS):
        raise DeliveryError("four-camera source inventory incomplete")
    for name, item in streams.items():
        relative = item.get("path", "")
        if not relative or Path(relative).is_absolute() or ".." in Path(relative).parts:
            raise DeliveryError(f"unsafe or missing {name} path")
        file = source_root / relative
        if not file.is_file() or sha256(file.read_bytes()).hexdigest() != item.get("sha256"):
            raise DeliveryError(f"{name} bytes missing or changed")
    frame_ids = receipt.get("frame_ids")
    if not isinstance(frame_ids, list) or len(frame_ids) != 900:
        raise DeliveryError("full original frame map missing")
    if any(b != a + 1 for a, b in zip(frame_ids, frame_ids[1:])):
        raise DeliveryError("frame map not contiguous")
    if not set(measurement.get("approach_frame_ids", [])).issubset(frame_ids):
        raise DeliveryError("approach frames not in original acquisition")
    if not set(measurement.get("traversal_frame_ids", [])).issubset(frame_ids):
        raise DeliveryError("traversal frames not in original acquisition")
    if not measurement.get("source_sha256"):
        raise DeliveryError("measurement provenance absent")
    if receipt.get("candidate") not in ("primary", "fallback1", "fallback2"):
        raise DeliveryError("candidate-selection receipt absent")
    return {"case_id": expected_case, "recorded_only_join": "passed", "legal_conclusion": None}
